// Comprehensive Geographic Hierarchy & Exhaustive Crop Catalog for Andhra Pradesh & Telangana
// Structured for seamless multi-state expansion (e.g. Karnataka, Tamil Nadu, Maharashtra).
// Sourced from Official Local Government Directory (LGD), Ministry of Panchayati Raj, Govt of India.

export type VillageInfo = {
  village: string;
  native?: string;
  pincode?: string;
  code?: string;
  category?: string;
  status?: string;
};

export type VillageData = string;

export type MandalData = {
  [mandalName: string]: VillageData[];
};

export type DistrictData = {
  [districtName: string]: MandalData;
};

export type StateHierarchy = {
  [stateName: string]: DistrictData;
};

export type CropCategory =
  | "All"
  | "Cereals & Millets"
  | "Pulses"
  | "Oilseeds"
  | "Commercial & Fiber"
  | "Spices & Condiments"
  | "Fruits & Plantation"
  | "Vegetables";

export type CropItem = {
  name: string;
  teluguName: string;
  category: Exclude<CropCategory, "All">;
  tag: string;
  key: string;
  majorSeasons: ("Kharif" | "Rabi" | "Summer")[];
};

