export const ALL_STATES = Object.keys(REGIONAL_HIERARCHY);

export function getDistrictsForState(state: string): string[] {
  const data = REGIONAL_HIERARCHY[state];
  return data ? Object.keys(data).sort() : [];
}

export function getMandalsForDistrict(state: string, district: string): string[] {
  const stateData = REGIONAL_HIERARCHY[state];
  if (!stateData) return [];
  const districtData = stateData[district];
  return districtData ? Object.keys(districtData).sort() : [];
}

export function getVillagesForMandal(state: string, district: string, mandal: string): string[] {
  const stateData = REGIONAL_HIERARCHY[state];
  if (!stateData) return [];
  const districtData = stateData[district];
  if (!districtData) return [];
  const villages = districtData[mandal];
  return villages ? [...villages].sort() : [];
}

// In-memory cache for all fetched villages
const villageCache = new Map<string, VillageInfo[]>();

// Full dynamic loader for complete official LGD villages (all 29,239 villages)
export async function fetchOfficialVillages(
  apiBase: string,
  state: string,
  district: string,
  mandal: string
): Promise<VillageInfo[]> {
  const cacheKey = `${state}_${district}_${mandal}`.toLowerCase();
  if (villageCache.has(cacheKey)) {
    return villageCache.get(cacheKey)!;
  }

  // 1. Try Live Backend API
  try {
    const url = `${apiBase}/locations/villages?state=${encodeURIComponent(state)}&district=${encodeURIComponent(district)}&mandal=${encodeURIComponent(mandal)}`;
    const res = await fetch(url);
    if (res.ok) {
      const data = await res.json();
      if (data.villages && Array.isArray(data.villages) && data.villages.length > 0) {
        villageCache.set(cacheKey, data.villages);
        return data.villages;
      }
    }
  } catch {
    // Fall back to static CDN
  }

  // 2. Try Static Vercel CDN JSON
  try {
    const filename = state.toLowerCase().includes("telangana") ? "telangana_villages.json" : "andhra_pradesh_villages.json";
    const res = await fetch(`/data/${filename}`);
    if (res.ok) {
      const dict = await res.json();
      const dictKey = `${district}___${mandal}`;
      if (dict[dictKey]) {
        const items = dict[dictKey];
        villageCache.set(cacheKey, items);
        return items;
      }
    }
  } catch {
    // Fall through to fallback
  }

  // 3. Synchronous built-in fallback
  const fallbackList = getVillagesForMandal(state, district, mandal);
  return fallbackList.map((v) => ({ village: v, native: "", pincode: "", code: "" }));
}
